"use strict";
const EBOOK_CATEGORIES = {
    Fiction: [
        "Novel",
        "Novella",
        "Short story",
        "Fantasy",
        "Science fiction",
        "Romance",
        "Mystery / Detective",
        "Thriller / Suspense",
        "Horror",
        "Historical fiction",
        "Adventure",
        "Literary fiction",
        "Young Adult (YA)",
    ],
    "Non-fiction": [
        "Self-help / Personal development",
        "Psychology",
        "Philosophy",
        "Biography / Autobiography / Memoir",
        "History",
        "Business & Finance",
        "Science",
        "Technology",
        "Health & Fitness",
        "Politics & Society",
        "True crime",
        "Travel",
        "Education / Textbooks",
        "Reference / Guides",
        "Essays",
        "Religion & Spirituality",
        "Cookbooks",
    ],
};
function titleKey(value) {
    return value
        .normalize("NFKC")
        .toLowerCase()
        .replace(/[\u0610-\u061a\u0640\u064b-\u065f\u0670\u06d6-\u06ed]/g, "")
        .replace(/[أإآٱ]/g, "ا")
        .replace(/ى/g, "ي")
        .replace(/[^\p{L}\p{N}]+/gu, " ")
        .trim();
}
function identityTitleKey(value) {
    return titleKey(value)
        .replace(/\b(?:a|an|the)\b/g, " ")
        .replace(/\s+/g, " ")
        .trim();
}
function authorListsMatch(left, right) {
    return left.some((a) => right.some((b) => {
        const x = titleKey(a);
        const y = titleKey(b);
        const tokenKey = (value) => value.split(" ").filter(Boolean).sort().join(" ");
        return (x === y ||
            tokenKey(x) === tokenKey(y) ||
            (x.length > 4 && y.length > 4 && (x.includes(y) || y.includes(x))));
    }));
}
function identityAliases(ebook) {
    return new Set([
        ebook.title,
        ...(ebook.sourceAliases ??
            (ebook.source === "source" ? (ebook.altTitle?.split("|") ?? []) : [])),
        ...(ebook.verifiedAliases ?? []),
    ]
        .filter((title) => Boolean(title?.trim()))
        .map(identityTitleKey)
        .filter(Boolean));
}
function explicitSourceIdentityMatch(left, right) {
    const a = left.sourceIdentity;
    const b = right.sourceIdentity;
    if (!a || !b)
        return false;
    return Boolean((a.anilistId && a.anilistId === b.anilistId) ||
        (a.googleBooksId && a.googleBooksId === b.googleBooksId) ||
        (a.openLibraryId && a.openLibraryId === b.openLibraryId) ||
        (a.wikidataId && a.wikidataId === b.wikidataId) ||
        (a.isbn && a.isbn === b.isbn));
}
function eBooksMatch(left, right) {
    if (left.id === right.id)
        return true;
    if (explicitSourceIdentityMatch(left, right))
        return true;
    const leftAliases = identityAliases(left);
    const sharedAliases = [...identityAliases(right)].filter((alias) => leftAliases.has(alias));
    if (!sharedAliases.length)
        return false;
    const leftPrimary = identityTitleKey(left.title);
    const rightPrimary = identityTitleKey(right.title);
    const crossLanguage = /\p{Script=Arabic}/u.test(left.title) !== /\p{Script=Arabic}/u.test(right.title);
    const leftExplicitAliases = new Set((left.sourceAliases ?? []).map(identityTitleKey));
    const rightExplicitAliases = new Set((right.sourceAliases ?? []).map(identityTitleKey));
    const leftVerifiedAliases = new Set((left.verifiedAliases ?? []).map(identityTitleKey));
    const rightVerifiedAliases = new Set((right.verifiedAliases ?? []).map(identityTitleKey));
    const leftTrustedAliases = new Set([...leftExplicitAliases, ...leftVerifiedAliases]);
    const rightTrustedAliases = new Set([...rightExplicitAliases, ...rightVerifiedAliases]);
    const crossLanguageAlias = crossLanguage &&
        sharedAliases.some((alias) => (leftTrustedAliases.has(alias) && alias === rightPrimary) ||
            (rightTrustedAliases.has(alias) && alias === leftPrimary) ||
            (leftTrustedAliases.has(alias) && rightTrustedAliases.has(alias)));
    if (crossLanguageAlias)
        return true;
    if (left.authors.length && right.authors.length)
        return authorListsMatch(left.authors, right.authors);
    return true;
}
function dedupeEBooks(ebooks) {
    const unique = new Map();
    for (const ebook of ebooks.flatMap((item) => item.books ?? [item]))
        unique.set(ebook.id, ebook);
    const groups = [];
    for (const ebook of unique.values()) {
        const group = groups.find((items) => items.some((item) => eBooksMatch(item, ebook)));
        if (group)
            group.push(ebook);
        else
            groups.push([ebook]);
    }
    return groups.map((items) => {
        const primary = items.find((item) => /\p{Script=Latin}/u.test(item.title) && !/\p{Script=Arabic}/u.test(item.title)) ?? items[0];
        const ordered = [primary, ...items.filter((item) => item.id !== primary.id)];
        return {
            ...primary,
            books: ordered.length > 1 ? ordered : undefined,
        };
    });
}
"use strict";
const EBOOK_FILTER_GENRES = [
    "Cheat system",
    "Comedy",
    "Cultivation",
    "Fantasy",
    "LitRPG",
    "Mystery",
    "Romance",
    "Sci-fi",
    "Slice of Life",
    "Sports",
    "Thriller",
];
const normalizedStatus = (value) => {
    const status = value?.toLocaleLowerCase() ?? "";
    if (/complete|finished/.test(status))
        return "completed";
    if (/hiatus|paused|break/.test(status))
        return "hiatus";
    if (/ongoing|releasing|publishing|current/.test(status))
        return "ongoing";
    return "";
};
const normalizedLanguage = (value) => {
    const language = value?.trim().toLocaleLowerCase() ?? "";
    if (["zh", "zho", "chi", "cn", "chinese"].includes(language))
        return "chinese";
    if (["ko", "kor", "kr", "korean"].includes(language))
        return "korean";
    if (["ja", "jpn", "jp", "japanese"].includes(language))
        return "japanese";
    return "";
};
const GENRE_ALIASES = {
    "cheat system": ["cheat system", "system"],
    "sci fi": ["sci fi", "science fiction"],
    mystery: ["mystery", "detective"],
    thriller: ["thriller", "suspense"],
};
const normalizedGenre = (value) => value
    .normalize("NFKD")
    .toLocaleLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();
function ebookMatchesGenre(genres, selected) {
    const wanted = normalizedGenre(selected);
    if (!wanted)
        return true;
    const aliases = GENRE_ALIASES[wanted] ?? [wanted];
    return genres.some((genre) => {
        const candidate = normalizedGenre(genre);
        return aliases.some((alias) => candidate === alias || candidate.includes(alias) || alias.includes(candidate));
    });
}
function ebookSourceBrowseTag(status, sort) {
    if (status !== "any")
        return `status:${status}`;
    return `sort:${sort}`;
}
function applyEBookBrowseFilters(books, filters) {
    const filtered = books.filter((book) => (filters.status === "any" || normalizedStatus(book.status) === filters.status) &&
        (filters.language === "any" ||
            normalizedLanguage(book.originalLanguage) === filters.language));
    if (filters.sort === "popular")
        return filtered;
    return [...filtered].sort((left, right) => {
        if (filters.sort === "name")
            return left.title.localeCompare(right.title);
        if (filters.sort === "chapters")
            return (right.chapters ?? -1) - (left.chapters ?? -1);
        if (filters.sort === "rating")
            return (right.score ?? -1) - (left.score ?? -1);
        return ((right.trendingScore ?? right.score ?? right.chapters ?? -1) -
            (left.trendingScore ?? left.score ?? left.chapters ?? -1));
    });
}
"use strict";
function ebookTitleForLanguage(ebook, language) {
    if (language === "auto" || language === "original")
        return ebook.title;
    const candidates = [ebook.title, ...(ebook.altTitle?.split("|") ?? [])]
        .map((title) => title.trim())
        .filter(Boolean);
    const match = language === "ar"
        ? candidates.find((title) => /[\u0600-\u06ff]/.test(title))
        : candidates.find((title) => /[a-z]/i.test(title) && !/[\u0600-\u06ff\u3040-\u30ff\u3400-\u9fff]/.test(title));
    return match ?? ebook.title;
}

function harborEBookCatalog(text) {
  const input = JSON.parse(text);
  if (input.operation === "definitions") return JSON.stringify({categories:EBOOK_CATEGORIES,genres:EBOOK_FILTER_GENRES});
  if (input.operation === "tag") return JSON.stringify(ebookSourceBrowseTag(input.status,input.sort));
  const grouped = dedupeEBooks(input.books);
  const filtered = applyEBookBrowseFilters(grouped,input.filters);
  const wanted = input.filters.genre || (input.filters.group === "All" ? "" : input.filters.group);
  const genres = !wanted ? [] : input.filters.genre ? [wanted] : [wanted,...(EBOOK_CATEGORIES[input.filters.group]??[])];
  return JSON.stringify(filtered.filter(book => !wanted || genres.some(genre => ebookMatchesGenre(book.genres??[],genre)))
    .map(book=>({id:book.id,title:ebookTitleForLanguage(book,input.titleLanguage),routes:(book.books??[book]).map(item=>item.id)})));
}
